// Six systems run here, in order, with retries -- the reason n8n exists in
// frontdesk at all. Nothing in this workflow is on the call path.
//
// This node only normalises what the transport sent. The envelope is read
// defensively: voice platforms (Vapi, Retell, LiveKit) each nest the call
// object differently, and none of their shapes are worth trusting blindly.

const body = $input.first().json;
const flat = (v) => (typeof v === 'object' && v !== null ? v : {});
const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

const call = flat(body.call || body.data);
const contact = flat(body.contact);
const location = flat(body.location);

const call_id = str(body.call_id || body.callId || body.id || call.id || call.call_id || '');
const location_id = str(body.location_id || body.locationId || location.id || location.locationId || '');
const contact_id = str(body.contact_id || body.contactId || contact.id || contact.contactId || '');
const from_phone = str(body.from_phone || body.from || body.caller_number || contact.phone || '');
const started_at = str(body.started_at || body.startTime || call.startedAt || call.started_at || '');
const ended_at = str(body.ended_at || body.endTime || call.endedAt || call.ended_at || new Date().toISOString());
const duration_secs = Number(body.duration_secs || call.durationSecs || call.duration || 0);
const recording_url = str(body.recording_url || body.recordingUrl || call.recordingUrl || '');

const transcript = Array.isArray(body.transcript)
  ? body.transcript
  : Array.isArray(call.transcript)
    ? call.transcript
    : [];
const transcript_text = transcript
  .map(t => {
    const role = str(t.role || t.speaker || 'caller');
    const text = str(t.text || t.content || t.message || '');
    const at = str(t.at || t.timestamp || '');
    return (at ? at + ' ' : '') + role + ': ' + text;
  })
  .join('\n');

return [{
  json: {
    call_id,
    location_id: location_id || call_id,
    contact_id,
    from_phone,
    started_at: started_at || null,
    ended_at,
    duration_secs,
    recording_url,
    transcript,
    transcript_text,
    transcript_json: JSON.stringify(transcript),
    has_transcript: transcript_text.trim().length > 0
  }
}];

// Claude returns text; the prompt asks for strict JSON, but models drift.
// This parses tolerantly and degrades to a skipped extraction rather than
// passing half-parsed garbage downstream to be stored as truth.

const body = $input.first().json;
const raw = typeof body === 'string' ? body : JSON.stringify(body || {});

let parsed = null;
const statusCode = body.statusCode || body.status || body.error ? String(body.error ? 'error' : (body.statusCode || body.status)) : '';

// Anthropic errors land here via neverError: { type: 'error', error: {...} }
if (body && body.type === 'error') {
  return [{ json: { processed: false, reason: 'anthropic error: ' + (body.error && body.error.message || statusCode) } }];
}

let text = '';
if (Array.isArray(body && body.content)) {
  text = body.content.map(b => (b && b.type === 'text' ? b.text : '')).join('\n');
} else if (typeof (body && body.text) === 'string') {
  text = body.text;
}

if (!text.trim()) {
  return [{ json: { processed: false, reason: 'no text in model response' } }];
}

const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start !== -1 && end > start) {
  try { parsed = JSON.parse(text.slice(start, end + 1)); } catch (e) { parsed = null; }
}

if (!parsed) {
  return [{ json: { processed: false, reason: 'model output was not parseable JSON' } }];
}

return [{
  json: {
    processed: true,
    summary: String(parsed.summary || ''),
    intent: String(parsed.intent || 'other'),
    outcome: parsed.outcome ? String(parsed.outcome) : null,
    escalated: parsed.escalated === true,
    needs_followup: parsed.needs_followup === true,
    sentiment: String(parsed.sentiment || 'neutral')
  }
}];
